<section class="section-wrap dashboard-page"><div class="dashboard-heading"><div><p class="eyebrow">YOUR SHIFA SPACE</p><h1>Your orders<span class="brand-dot">.</span></h1><p>Everything you’ve chosen, all in one place.</p></div><a class="button button-outline" href="<?= $e($base) ?>/profile">Edit profile ↗</a></div><div class="account-tabs"><a href="<?= $e($base) ?>/account/orders" class="active">Orders</a><a href="<?= $e($base) ?>/profile">Profile</a></div><?php if (!$orders): ?><div class="empty-state"><span>◌</span><h2>Your next good thing is out there.</h2><p>When you place an order, you’ll find it here.</p><a class="button button-dark" href="<?= $e($base) ?>/shop">Explore the collection</a></div><?php else: ?><div class="data-card order-table"><div class="table-head"><span>Order</span><span>Date</span><span>Status</span><span>Total</span><span></span></div><?php foreach ($orders as $order): ?><a class="table-row" href="<?= $e($base) ?>/account/order?id=<?= (int) $order['id'] ?>"><b>#<?= str_pad((string) $order['id'], 5, '0', STR_PAD_LEFT) ?></b><span><?= $e(date('M j, Y', strtotime($order['created_at']))) ?></span><span><i class="status-pill status-<?= $e($order['status']) ?>"><?= $e(ucfirst($order['status'])) ?></i></span><b><?= number_format((float) $order['total'], 2) ?> JOD</b><span class="row-arrow">↗</span></a><?php endforeach; ?></div><?php endif; ?></section>
